import{_ as o,c as a,a2 as n,o as e}from"./chunks/framework.Bzjhwp8w.js";const r="/dllm/assets/0aa642624dd5ba4e796fa2252dde88b8.CHagBT_q.png",p=JSON.parse('{"title":"Document QA","description":"Document QA","frontmatter":{"title":"Document QA","description":"Document QA","layout":"doc"},"headers":[],"relativePath":"langflow/tutorials-document-qa.md","filePath":"langflow/tutorials-document-qa.md"}'),l={name:"langflow/tutorials-document-qa.md"};function s(i,t,c,g,d,u){return e(),a("div",null,t[0]||(t[0]=[n('<h1 id="document-qa" tabindex="-1">Document QA <a class="header-anchor" href="#document-qa" aria-label="Permalink to &quot;Document QA&quot;">​</a></h1><p>构建一个可以从本地内存加载文档的问答聊天机器人。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><hr><ul><li><a href="/dllm/get-started-installation.html">安装并运行 Langflow</a></li><li><a href="https://platform.openai.com/" target="_blank" rel="noreferrer">创建 OpenAI API 密钥</a></li></ul><h2 id="创建文档-qa-流程" tabindex="-1">创建文档 QA 流程 <a class="header-anchor" href="#创建文档-qa-流程" aria-label="Permalink to &quot;创建文档 QA 流程&quot;">​</a></h2><ol><li>在 Langflow 仪表板中，点击 <strong>New Flow</strong>。</li><li>选择 <strong>Document QA</strong>。</li><li><strong>Document QA</strong> 流程已创建。</li></ol><p><img src="'+r+'" alt=""></p><p>该流程由标准聊天机器人组成，包含<strong>聊天输入</strong>、<strong>提示</strong>、<strong>OpenAI</strong> 和 <strong>聊天输出</strong>组件，同时还结合了一个<strong>文件</strong>组件，该组件用于从本地机器加载文件。<strong>解析数据</strong>用于将文件中的数据转换为<strong>提示</strong>组件中的<code>{Document}</code>格式。<strong>提示</strong>组件被指示根据<code>{Document}</code>的内容来回答问题。这使得<strong>OpenAI</strong>组件能获得其原本无法访问的上下文信息。</p><h3 id="运行文档-qa-流程" tabindex="-1">运行文档 QA 流程 <a class="header-anchor" href="#运行文档-qa-流程" aria-label="Permalink to &quot;运行文档 QA 流程&quot;">​</a></h3><ol><li><p>要选择您想加载的文档，在 <strong>File</strong> 组件中，点击 <strong>Path</strong> 字段。选择一个本地文件，然后点击 <strong>Open</strong>。文件名会出现在该字段中。</p></li><li><p>点击 <strong>Playground</strong> 按钮。在这里，您可以与有权限访问您文档内容的 AI 进行对话。</p></li><li><p>输入关于文档内容的问题并按下 Enter。您应该会看到一个上下文相关的回答。</p></li></ol>',11)]))}const h=o(l,[["render",s]]);export{p as __pageData,h as default};
